<script setup> /** * Vue d'émargement et vérification des candidats via scan de Code QR. */ import { ref, onMounted } from'vue' import { useRoute, useRouter } from'vue-router' import api from'../services/api' import { useModalStore } from'../stores/modal' import { parseBackendError } from'../utils/errorHandler' import DashboardLayout from'../components/layouts/DashboardLayout.vue' import { ArrowLeft, Loader2, CheckCircle2, XCircle, AlertCircle, Clock, Calendar, Phone, Mail, User, Activity, FileText } from'lucide-vue-next' const route = useRoute() const router = useRouter() const modalStore = useModalStore() const candidateId = route.params.candidateId const loading = ref(true) const error = ref(null) const candidat = ref(null) const candidature = ref(null) const participations = ref([]) const updatingId = ref(null) const motifs = ref({}) onMounted(async () => { await fetchScanDetails() }) const fetchScanDetails = async () => { loading.value = true error.value = null try { const response = await api.get(`evaluations/candidat/${candidateId}/scan-details/`) candidat.value = response.data.candidat candidature.value = response.data.candidature participations.value = response.data.participations || [] // Initialize motifs dictionary participations.value.forEach(p => { motifs.value[p.id] = p.motif ||'' }) } catch (err) { console.error(err) error.value = err.response?.data?.detail ||"Impossible de charger les détails du candidat scanné." } finally { loading.value = false } } const updateStatus = async (participationId, newStatus) => { updatingId.value = participationId try { const payload = { statut: newStatus, motif: motifs.value[participationId] } const response = await api.patch(`evaluations/participations/${participationId}/changer-statut/`, payload) // Update local state const index = participations.value.findIndex(p => p.id === participationId) if (index !== -1) { participations.value[index] = response.data } } catch (err) { console.error(err) await modalStore.showAlert( parseBackendError(err), 'Erreur', 'danger' ) } finally { updatingId.value = null } } const saveMotif = async (participationId) => { updatingId.value = participationId try { const p = participations.value.find(p => p.id === participationId) const payload = { statut: p.statut, motif: motifs.value[participationId] } const response = await api.patch(`evaluations/participations/${participationId}/changer-statut/`, payload) // Update local state const index = participations.value.findIndex(p => p.id === participationId) if (index !== -1) { participations.value[index] = response.data } await modalStore.showAlert("Remarque enregistrée avec succès.","Enregistrement réussi","success" ) } catch (err) { console.error(err) await modalStore.showAlert( parseBackendError(err),"Erreur","danger" ) } finally { updatingId.value = null } } const getStatusBadgeClass = (status) => { switch (status) { case'REUSSIE': return'bg-white text-[#01313E] border-[#01313E]' case'ECHOUEE': return'bg-white text-[#E30046] border-[#E30046]' case'ABSENT': return'bg-white text-[#01313E] border-[#01313E]/10' case'EN_COURS': return'bg-white text-[#01313E] border-[#01313E]' case'ANNULEE': return'bg-white text-[#E30046] border-[#E30046]' default: return'bg-white text-[#01313E] border-[#01313E]' } } const getStatusLabel = (status) => { switch (status) { case'REUSSIE': return'Réussie' case'ECHOUEE': return'Échouée' case'ABSENT': return'Absent' case'EN_COURS': return'En cours' case'ANNULEE': return'Annulée' default: return'En attente' } } </script> <template> <DashboardLayout> <template #header> <div class="flex items-center"> <button @click="router.back()" class="p-2 mr-3 text-[#01313E]/60 hover:text-[#01313E]/80 hover:bg-white rounded-full transition-colors" > <ArrowLeft class="w-5 h-5"/> </button> <h2 class="text-xl font-semibold text-[#01313E]">Suivi d'émargement QR Code</h2> </div> </template> <div v-if="loading"class="flex justify-center items-center py-20"> <Loader2 class="w-10 h-10 animate-spin text-[#E30046]"/> </div> <div v-else-if="error"class="bg-white border-l-4 border-[#E30046] p-6 rounded-xl text-[#E30046] max-w-xl mx-auto flex items-start"> <AlertCircle class="w-6 h-6 mr-3 flex-shrink-0 mt-0.5 text-[#E30046]"/> <div> <h4 class="font-bold text-[#E30046] mb-1">Erreur de scan</h4> <p class="text-sm">{{ error }}</p> <button @click="router.push('/candidatures')" class="mt-4 px-4 py-2 bg-[#E30046] text-white rounded-lg text-xs font-semibold hover:bg-[#E30046] transition-colors" > Retourner aux candidatures </button> </div> </div> <div v-else class="grid grid-cols-1 lg:grid-cols-3 gap-8 max-w-6xl mx-auto"> <!-- Colonne Fiche Candidat & Candidature --> <div class="space-y-6"> <!-- Fiche Candidat --> <div class="bg-white rounded-2xl border border-gray-150 p-6"> <div class="flex items-center space-x-4 mb-6"> <div class="w-14 h-14 rounded-full bg-white flex items-center justify-center text-[#E30046]"> <User class="w-7 h-7"/> </div> <div> <h3 class="font-bold text-lg text-[#01313E]">{{ candidat.prenom }} {{ candidat.nom }}</h3> <span class="px-2 py-0.5 bg-white text-[#01313E]/80 text-xxs font-bold uppercase rounded-md">Candidat</span> </div> </div> <div class="space-y-4 text-sm text-[#01313E]/80"> <div class="flex items-center"> <Mail class="w-4 h-4 text-[#01313E]/60 mr-3 flex-shrink-0"/> <span class="truncate":title="candidat.email">{{ candidat.email }}</span> </div> <div class="flex items-center"v-if="candidat.telephone"> <Phone class="w-4 h-4 text-[#01313E]/60 mr-3 flex-shrink-0"/> <span>{{ candidat.telephone }}</span> </div> <div class="flex items-center"> <span class="text-[#01313E]/60 font-semibold w-12 text-xs">Genre:</span> <span>{{ candidat.sexe ==='HOMME' ?'Homme' :'Femme' }}</span> </div> </div> </div> <!-- Fiche Candidature --> <div class="bg-white rounded-2xl border border-gray-150 p-6"> <h4 class="font-bold text-[#01313E] mb-4 pb-2 border-b border-[#01313E]/10 flex items-center"> <FileText class="w-4 h-4 mr-2 text-[#E30046]"/> Détails du dossier </h4> <div class="space-y-3 text-sm text-[#01313E]/80"> <div class="flex justify-between"> <span class="text-[#01313E]/60">N° Candidature:</span> <span class="font-semibold text-gray-950">{{ candidature.numero }}</span> </div> <div class="flex justify-between"> <span class="text-[#01313E]/60">Campagne:</span> <span class="font-semibold text-gray-950 text-right truncate max-w-[150px]">{{ candidature.campagne_nom }}</span> </div> <div class="flex justify-between"> <span class="text-[#01313E]/60">Cohorte:</span> <span class="font-semibold text-gray-950">{{ candidature.cohorte_nom }}</span> </div> <div class="flex justify-between items-center pt-2"> <span class="text-[#01313E]/60">Statut Dossier:</span> <span class="px-2.5 py-0.5 text-xs font-semibold rounded-full" :class="{'bg-white text-[#01313E]': candidature.statut ==='EN_ATTENTE','bg-white text-[#01313E]': candidature.statut ==='EN_COURS','bg-white text-[#01313E]': candidature.statut ==='TERMINEE' }" > {{ candidature.statut ==='EN_ATTENTE' ?'En attente' : candidature.statut ==='EN_COURS' ?'En cours' :'Terminée' }} </span> </div> </div> </div> </div> <!-- Colonne Suivi des Étapes / Émargement --> <div class="lg:col-span-2 space-y-6"> <div class="bg-white rounded-2xl border border-gray-150 p-6"> <div class="flex items-center justify-between mb-6"> <h3 class="font-bold text-lg text-[#01313E] flex items-center"> <Activity class="w-5 h-5 mr-2 text-[#E30046]"/> Étapes de recrutement & Émargement </h3> <span class="text-xs text-[#01313E]/60 font-semibold">{{ participations.length }} étape(s)</span> </div> <div class="space-y-6"> <div v-if="participations.length === 0"class="text-center py-10 text-[#01313E]/60 text-sm"> Aucune étape de recrutement configurée pour la cohorte de cette campagne. </div> <div v-else v-for="part in participations" :key="part.id" class="p-5 border border-[#01313E]/10 rounded-xl space-y-4 hover:border-[#01313E]/10 transition-colors bg-white relative" > <!-- Info Etape --> <div class="flex items-start justify-between flex-wrap gap-2"> <div class="flex items-center space-x-3"> <span class="w-6 h-6 bg-white text-[#E30046] rounded-full flex items-center justify-center font-bold text-xs"> {{ part.etape_detail.ordre + 1 }} </span> <h4 class="font-bold text-[#01313E] text-base">{{ part.etape_detail.nom }}</h4> </div> <span class="px-2.5 py-0.5 text-xs font-semibold rounded-full border" :class="getStatusBadgeClass(part.statut)" > {{ getStatusLabel(part.statut) }} </span> </div> <!-- Émargement boutons de raccourci --> <div class="flex flex-wrap gap-2 pt-2"> <button @click="updateStatus(part.id,'EN_COURS')" :disabled="updatingId === part.id" class="px-3 py-1.5 border border-[#01313E] bg-white text-[#01313E] hover:bg-white disabled:opacity-50 text-xs font-semibold rounded-lg transition-colors flex items-center" > <Clock class="w-3.5 h-3.5 mr-1"/> Démarrer l'étape </button> <button @click="updateStatus(part.id,'REUSSIE')" :disabled="updatingId === part.id" class="px-3 py-1.5 border border-[#01313E] bg-white text-[#01313E] hover:bg-white disabled:opacity-50 text-xs font-semibold rounded-lg transition-colors flex items-center" > <CheckCircle2 class="w-3.5 h-3.5 mr-1"/> Valider (Réussie) </button> <button @click="updateStatus(part.id,'ECHOUEE')" :disabled="updatingId === part.id" class="px-3 py-1.5 border border-[#E30046] bg-white text-[#E30046] hover:bg-white disabled:opacity-50 text-xs font-semibold rounded-lg transition-colors flex items-center" > <XCircle class="w-3.5 h-3.5 mr-1"/> Échouer </button> <button @click="updateStatus(part.id,'ABSENT')" :disabled="updatingId === part.id" class="px-3 py-1.5 border border-[#01313E]/10 bg-white text-[#01313E]/80 hover:bg-white disabled:opacity-50 text-xs font-semibold rounded-lg transition-colors flex items-center" > <User class="w-3.5 h-3.5 mr-1"/> Marquer absent </button> </div> <!-- Remarques / Motif --> <div class="pt-3 border-t border-[#01313E]/10 flex gap-3 items-end"> <div class="flex-1"> <label class="block text-xxs font-semibold text-[#01313E]/60 uppercase mb-1">Remarques / Observations / Motif d'échec ou absence</label> <input type="text" v-model="motifs[part.id]" placeholder="Saisir des notes d'évaluation ou motif..." class="w-full px-3 py-1.5 border border-[#01313E]/10 rounded-lg text-xs focus:outline-none focus:ring-1 focus:focus:border-[#E30046]" /> </div> <button @click="saveMotif(part.id)" :disabled="updatingId === part.id" class="px-3 py-1.5 bg-[#01313E] text-white text-xs font-semibold rounded-lg hover:bg-[#01313E] disabled:opacity-50 transition-colors" > <span v-if="updatingId === part.id"><Loader2 class="w-3.5 h-3.5 animate-spin"/></span> <span v-else>Enregistrer</span> </button> </div> </div> </div> </div> </div> </div> </DashboardLayout> </template> 